const input = $input.first().json;
const contractVersion = '1.0';
const testMode = input.testMode !== false;
const correlationId = typeof input.correlationId === 'string' && /^[A-Za-z0-9._:-]{1,128}$/.test(input.correlationId) ? input.correlationId : crypto.randomUUID();
const base = {contractVersion,testMode,correlationId,allowAction:false};
const fail = (code,message) => [{json:{...base,ok:false,status:'denied',reason:code,error:{code,message}}}];
const allowed = new Set(['contractVersion','testMode','phase','correlationId','idempotencyKey','action','decision','requestedAt','expiresAt','timeoutSeconds','now']);
if (Object.keys(input).some((key) => !allowed.has(key))) return fail('INVALID_REQUEST','Input contains unknown fields');
if (input.contractVersion !== undefined && input.contractVersion !== contractVersion) return fail('UNSUPPORTED_CONTRACT','contractVersion must be 1.0');
const phase = input.phase ?? 'request';
if (!['request','resolve'].includes(phase)) return fail('INVALID_PHASE','phase must be request or resolve');
if (typeof input.idempotencyKey !== 'string' || !/^[A-Za-z0-9._:-]{8,128}$/.test(input.idempotencyKey)) return fail('INVALID_IDEMPOTENCY_KEY','A safe idempotencyKey is required');
const now = new Date(input.now ?? Date.now());
if (Number.isNaN(now.getTime())) return fail('INVALID_TIME','now must be an ISO timestamp');
if (phase === 'request') {
  const action = input.action;
  if (!action || typeof action.type !== 'string' || !/^[a-z][a-z0-9._-]{1,63}$/.test(action.type) || typeof action.summary !== 'string' || action.summary.trim().length < 1 || action.summary.length > 500) return fail('INVALID_ACTION','action.type and a 1..500 character summary are required');
  const timeoutSeconds = input.timeoutSeconds ?? 3600;
  if (!Number.isInteger(timeoutSeconds) || timeoutSeconds < 60 || timeoutSeconds > 86400) return fail('INVALID_TIMEOUT','timeoutSeconds must be 60..86400');
  const requestedAt = new Date(input.requestedAt ?? now);
  const expiresAt = new Date(input.expiresAt ?? requestedAt.getTime() + timeoutSeconds * 1000);
  if (Number.isNaN(requestedAt.getTime()) || Number.isNaN(expiresAt.getTime()) || expiresAt <= requestedAt) return fail('INVALID_TIME','Approval expiry must be after request time');
  return [{json:{...base,ok:true,status:'pending',reason:'AWAITING_EXPLICIT_DECISION',idempotencyKey:input.idempotencyKey,request:{action:{type:action.type,summary:action.summary.trim(),risk:['low','medium','high'].includes(action.risk)?action.risk:'high'},requestedAt:requestedAt.toISOString(),expiresAt:expiresAt.toISOString()}}}];
}
const expiresAt = new Date(input.expiresAt);
if (Number.isNaN(expiresAt.getTime())) return fail('INVALID_TIME','expiresAt is required for resolve');
if (now >= expiresAt) return [{json:{...base,ok:true,status:'expired',reason:'APPROVAL_TIMEOUT',idempotencyKey:input.idempotencyKey,expiresAt:expiresAt.toISOString()}}];
const state = typeof input.decision?.state === 'string' ? input.decision.state.toLowerCase() : '';
if (state !== 'approved') return [{json:{...base,ok:true,status:'denied',reason:state === 'denied' ? 'EXPLICIT_DENIAL' : 'AMBIGUOUS_DECISION',idempotencyKey:input.idempotencyKey,expiresAt:expiresAt.toISOString()}}];
if (typeof input.decision.approverRef !== 'string' || !/^[A-Za-z0-9._:-]{3,128}$/.test(input.decision.approverRef)) return fail('INVALID_APPROVER','Approved decision requires an opaque approverRef');
return [{json:{...base,ok:true,status:'approved',reason:'EXPLICIT_APPROVAL',allowAction:true,idempotencyKey:input.idempotencyKey,expiresAt:expiresAt.toISOString(),decision:{state:'approved',approverRef:input.decision.approverRef}}}];
